      if (b.pullLeftovers !== false) {
        job.hint = 'Leftover Airbnb missing-only pull…';
        job.updatedAt = Date.now();
        try {
          const pullJob = {
            id: 'pip-' + Date.now().toString(36),
            status: 'starting', month: month, channel: 'airbnb',
            body: Object.assign({}, b, { month: month, channel: 'airbnb' }),
            by: 'agent-leftover', hint: null, error: null, saved: [], errors: [],
            createdAt: Date.now(), updatedAt: Date.now()
          };
          _piPullJobs.set(pullJob.id, pullJob);
          await piExecutePullJob(pullJob);
          const pullDeadline = Date.now() + 90 * 60 * 1000;
          while (Date.now() < pullDeadline) {
            if (pullJob.status === 'done' || pullJob.status === 'error' || pullJob.status === 'cancelled') break;
            job.hint = pullJob.hint || job.hint;
            job.updatedAt = Date.now();
