          }
        } catch (ePull) {
          leftover.errors.push({ error: ePull.message || String(ePull) });
        }
      }
      job.hint = 'Reconciling Booking + building Excel…';
      job.updatedAt = Date.now();
      const rows = await piLoadVaultRows(month);
      const bks = await piLoadDbBookings();
      const apts = await piLoadDbApts();
