      const cards = await piLoadAccountants();
      const emailPlan = piAgent.planAccountantEmails(cards, pack);
      const report = piAgent.buildAgentReport({ month: month, pack: pack, leftover: leftover, emailPlan: emailPlan, status: pack.blocked ? 'blocked' : 'ready' });
      if (!pack.blocked && emailPlan.sent.length && b.send !== false) {
        if (!emailConfigured()) throw new Error('Email is not configured');
        job.hint = 'Emailing accountants…';
        job.updatedAt = Date.now();
        const emailed = [];
        for (const c of emailPlan.sent) {
          const mailAtts = [];
          if (c.attachExcel && pack.xlsBuf) mailAtts.push({ filename: pack.xlsName, content: pack.xlsBuf, contentType: 'application/vnd.ms-excel' });
          if (c.attachPdfs) {
            for (const r of pack.pdfRows) {
              mailAtts.push({ filename: r.filename || (r.channel + '.pdf'), content: Buffer.from(r.data, 'base64'), contentType: r.mime || 'application/pdf' });
            }
          }
          if (!mailAtts.length) continue;
          await piSendAccountantMail(c.email, 'PLATFORM INVOICES ' + month, 'Platform invoice pack for ' + month + '.\n', mailAtts);
          emailed.push({ email: c.email, pdfs: !!c.attachPdfs, excel: !!c.attachExcel });
        }
        report.emailed = emailed;
        report.status = 'sent';
      }
      await piPersistAgentReport(report);
      job.report = report;
